mapper.select:
select mn.* from Progress_Declaration_Dtl mn left join Progress_Declaration pd on pd.id=mn.pd_id
pd.state = 7
and pd.id = #{id}

select mn.*,pd.Create_Uid as createUid,pd.Create_Uname as createUname,pd.Create_Time as createTime from Progress_Declaration_Dtl mn left join Progress_Declaration pd on pd.id=mn.pd_id
pd.state = 7
and mn.pd_id = #{id}
